AssistantMessageToolRequest(name='create', tool_call_id='tooluse_oOb7aidQkT5yk9l0oYLlhL', arguments={'file_text': "class ContactForm {
  constructor() {
    this.form = document.getElementById('contact-form');
    this.fullNameInput = document.getElementById('full-name');
    this.emailInput = document.getElementById('email');
    this.phoneInput = document.getElementById('phone');
    this.emailError = document.getElementById('email-error');
    this.phoneError = document.getElementById('phone-error');

    this.setupEventListeners();
  }

  setupEventListeners() {
    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    this.emailInput.addEventListener('blur', () => this.validateEmail());
    this.phoneInput.addEventListener('blur', () => this.validatePhone());
  }

  validateEmail() {
    const email = this.emailInput.value.trim();
    const isValid = this.isValidEmail(email);

    this.emailInput.setAttribute('aria-invalid', !isValid && email !== '');

    if (!isValid && email !== '') {
      this.emailError.textContent = 'Error: Enter a valid email address like name@example.com.';
    } else {
      this.emailError.textContent = '';
    }
  }

  validatePhone() {
    const phone = this.phoneInput.value.trim();
    const isValid = phone === '' || this.isValidPhone(phone);

    this.phoneInput.setAttribute('aria-invalid', !isValid);

    if (!isValid) {
      this.phoneError.textContent = 'Error: Enter a phone number in a valid format like (123) 456-7890 or +1-123-456-7890.';
    } else {
      this.phoneError.textContent = '';
    }
  }

  isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  isValidPhone(phone) {
    const phoneRegex = /^[\d\s\-().+]+$/;
    if (!phoneRegex.test(phone)) return false;

    const digitsOnly = phone.replace(/\D/g, '');
    return digitsOnly.length >= 10 && digitsOnly.length <= 15;
  }

  handleSubmit(e) {
    e.preventDefault();

    const fullName = this.fullNameInput.value.trim();
    const email = this.emailInput.value.trim();
    const phone = this.phoneInput.value.trim();

    let isFormValid = true;
    let firstInvalidField = null;

    if (!fullName) {
      this.fullNameInput.setAttribute('aria-invalid', 'true');
      isFormValid = false;
      firstInvalidField = firstInvalidField || this.fullNameInput;
    } else {
      this.fullNameInput.setAttribute('aria-invalid', 'false');
    }

    if (!email || !this.isValidEmail(email)) {
      this.emailInput.setAttribute('aria-invalid', 'true');
      this.emailError.textContent = 'Error: Enter a valid email address like name@example.com.';
      isFormValid = false;
      firstInvalidField = firstInvalidField || this.emailInput;
    } else {
      this.emailInput.setAttribute('aria-invalid', 'false');
      this.emailError.textContent = '';
    }

    if (phone && !this.isValidPhone(phone)) {
      this.phoneInput.setAttribute('aria-invalid', 'true');
      this.phoneError.textContent = 'Error: Enter a phone number in a valid format like (123) 456-7890 or +1-123-456-7890.';
      isFormValid = false;
      firstInvalidField = firstInvalidField || this.phoneInput;
    } else {
      this.phoneInput.setAttribute('aria-invalid', 'false');
      this.phoneError.textContent = '';
    }

    if (!isFormValid) {
      firstInvalidField.focus();
      return;
    }

    const formData = { fullName, email, phone };
    console.log('Form submitted:', formData);
    alert('Thank you for contacting us! We will get back to you soon.');
    this.form.reset();
    this.fullNameInput.setAttribute('aria-invalid', 'false');
    this.emailInput.setAttribute('aria-invalid', 'false');
    this.phoneInput.setAttribute('aria-invalid', 'false');
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new ContactForm();
});
